WITH cleaned AS (SELECT *, INITCAP(TRIM(account_type)) AS account_type_title FROM accounts WHERE balance > 67000), with_windows AS (SELECT id, account_type, balance, status, account_type_title, MAX(balance) OVER w_running AS running_max_balance, AVG(balance) OVER w_running AS running_avg_balance, SUM(balance) OVER w_running AS running_sum_balance FROM cleaned WINDOW w_running AS (PARTITION BY status, customer_id ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT id, account_type, balance, running_max_balance, running_avg_balance, running_sum_balance, LEAD(running_sum_balance, 1) OVER w_ordered AS next_running_sum_balance, SUM(running_avg_balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_running_avg_balance FROM with_windows WINDOW w_ordered AS (PARTITION BY status, account_type ORDER BY running_sum_balance, id)), scored AS (SELECT *, LAG(running_max_balance, 1, 0) OVER (PARTITION BY account_type ORDER BY running_sum_balance, id) AS prev_running_max_balance, PERCENT_RANK() OVER (PARTITION BY account_type ORDER BY next_running_sum_balance) AS next_running_sum_balance_percent_rank, LAG(running_max_balance, 2, 0) OVER (PARTITION BY account_type ORDER BY running_max_balance, id) AS prev_running_max_balance_2, LAST_VALUE(balance, TRUE) OVER (PARTITION BY account_type ORDER BY running_sum_balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_balance FROM enriched WHERE cumulative_running_avg_balance BETWEEN 242476 AND 310829), filtered AS (SELECT id, balance, running_avg_balance, next_running_sum_balance, cumulative_running_avg_balance, prev_running_max_balance, next_running_sum_balance_percent_rank, last_known_balance, CASE WHEN last_known_balance >= 70000 THEN 'High' WHEN last_known_balance >= 29000 THEN 'Medium' ELSE 'Low' END AS last_known_balance_level FROM scored WHERE balance BETWEEN 56000 AND 75000), totals AS (SELECT CASE WHEN running_avg_balance >= 67000 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_avg_balance_tier, CASE WHEN cumulative_running_avg_balance >= 384394 THEN 'PREMIUM' ELSE 'STANDARD' END AS cumulative_running_avg_balance_tier, SUM(balance) AS total_balance, PERCENTILE_APPROX(last_known_balance, ARRAY(0.25, 0.5, 0.75)) AS last_known_balance_quartiles, COUNT(DISTINCT id) AS distinct_ids FROM filtered GROUP BY running_avg_balance_tier, cumulative_running_avg_balance_tier) SELECT running_avg_balance_tier, cumulative_running_avg_balance_tier, total_balance, last_known_balance_quartiles FROM totals;
